> #Part 1#Directs my computer to the Fortnite Statistics datasetsetwd("/Users/saahir/Documents/Data101")#Reads the Fortnite Statistics dataset and assigns it to the data variabledata <- read.csv("Fortnite Statistics.csv")#Describing the data using tables and graphshead(data)str(data)summary(data)colors<- c('red','blue')boxplot(Placed~Mental.State,data=data,xlab="Mental State",ylab="Placement",         main="Boxplot of Mental State vs Placement",col=colors,border="black")#Simple Training/Test Set Splittinglibrary(rsample)library(caret)data$Mental.State = as.factor(data$Mental.State)#Need the set.seed statement for reproducibilityset.seed(15324)#Uses 80% of the dataset for training and leaves 20% for testingfgl_split <- initial_split(data, prop = 0.80)fgl_split#Training data settraining <- training(fgl_split)summary(training)#Test data settest <- testing(fgl_split)summary(test)#Doing Naive Bayes and Reporting Confusion Matrixlibrary(klaR)#Naive Bayesnb_mod <- NaiveBayes(Mental.State ~ Placed+Eliminations , data = training, method="class")pred <- predict(nb_mod, test)names(pred)#Confusion Matrixtab <- table(pred$class, test$Mental.State)confusion_nb <- caret::confusionMatrix(tab)confusion_nb#Part 2#Doing rpartlibrary(rpart)tree = rpart_mod=rpart(Mental.State ~ Placed+Eliminations, data = training, method = "class")library(rpart.plot)rpart.plot(tree)pred_rpart = predict(tree, test, type = "class")#Confusion Matrix for rparttab_rpart = table(pred_rpart, test$Mental.State)confusion_rpart <- caret::confusionMatrix(tab_rpart)confusion_rpart#Perform k-fold cross validation with k=5train_control <- trainControl(method = "cv", number = 5, savePredictions = TRUE)cv_nb = train(Mental.State ~ Placed+Eliminations, data = training, trControl = train_control, method = "nb")print(cv_nb)cv_rpart <- train(Mental.State ~ Placed+Eliminations, data = training, trControl = train_control, method = "rpart")print(cv_rpart)#Part 2.5#Comparing accuracy with rpart accuracyaccuracy_nb <- confusion_nb$overall["Accuracy"]accuracy_rpart <- confusion_rpart$overall["Accuracy"]cat("Accuracy for Naive Bayes:", accuracy_nb, "\n")cat("Accuracy for rpart:", accuracy_rpart, "\n")